import { describe, expect, it } from 'vitest';
import projects from '../../fixtures/dto/projects.json';
import poirotSessions from '../../fixtures/dto/sessions-poirot.json';

// Proves the M2-01 pipeline end to end: these fixtures are generated by the real Rust loaders
// (crates/heimdall-core/examples/export_dto_fixtures.rs) against fixtures/screenshot, not
// hand-typed here, so they can never silently drift from what the real commands serialise.
describe('DTO fixtures generated from the real Rust loaders', () => {
  it('lists all four fixtures/screenshot projects', () => {
    expect(projects).toHaveLength(4);
    expect(projects.map((p) => p.id)).toContain('-Users-fixture-Dev-poirot');
  });

  it("lists the poirot project's own main sessions, agent sessions excluded", () => {
    expect(poirotSessions).toHaveLength(7);
    expect(poirotSessions.every((s) => !s.isSidechain)).toBe(true);
    expect(poirotSessions.map((s) => s.id)).toContain('conv-001');
  });
});
